import json, pathlib
root=pathlib.Path('content')
def loc(en,ru): return {'en':en,'ru':ru}
def record(kind,id,en,ru,**kw):
 d=dict(id=id,kind=kind,name=loc(en,ru),description=loc('Demonstration record for exploring the archive. This is not a verified lore article.','Демонстрационная запись для изучения архива. Это не проверенная статья о лоре.'),alternativeNames=[],sources=[],demo=True,citationNeeded=True,evidenceStatus='approximate',relatedEntities=[],createdInVersion='demo-1',lastModifiedInVersion='demo-1',lastReviewedInVersion='demo-1',reviewStatus='incomplete'); d.update(kw); return d
def save(folder,d): (root/folder/(d['id']+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
for i,(en,ru,color) in enumerate([('Mondstadt','Мондштадт','#6b8c7c'),('Liyue','Ли Юэ','#b58a46'),('Inazuma','Инадзума','#9683aa'),('Sumeru','Сумеру','#7e965c'),('Fontaine','Фонтейн','#688da5'),('Natlan','Натлан','#b57560'),('Snezhnaya','Снежная','#8c9fa7'),("Khaenri’ah",'Каэнри’ах','#6b7189')]):
 id=['mondstadt','liyue','inazuma','sumeru','fontaine','natlan','snezhnaya','khaenriah'][i]
 save('regions',record('region',id,en,ru,color=color,civilizations=[],organizations=[]))
for id,en,ru,region,aliases in [('venti','Venti','Венти','mondstadt',['Barbatos','Барбатос']),('dvalin','Dvalin','Двалин','mondstadt',['Stormterror','Ужас бури']),('zhongli','Zhongli','Чжун Ли','liyue',['Morax','Моракс'])]:
 save('characters',record('character',id,en,ru,region=region,alternativeNames=aliases,titles=[],affiliations=[],species=loc('Not yet researched','Не исследовано'),status=loc('Not yet reviewed','Не проверено'),category='other',eras=['demo-era'],biography=loc('This article is an authoring scaffold. Add a sourced biography and connect it to canonical event records.','Это шаблон статьи. Добавьте биографию с источниками и ссылки на канонические записи событий.'),relatedLocations=['demo-'+region],relatedTerms=['irminsul'] if id=='venti' else []))
for id,en,ru in [('irminsul','Irminsul','Ирминсуль'),('ley-lines','Ley Lines','Артерии земли'),('celestia','Celestia','Селестия'),('archons','Archons','Архонты')]:
 save('terms',record('term',id,en,ru,category='research',definition=loc('Definition awaiting original-source research.','Определение ожидает исследования первоисточников.'),alternativeTranslations=['Ирминсуль','Irminsuul'] if id=='irminsul' else []))
for i,(r,x,y) in enumerate([('mondstadt',6800,2700),('liyue',5600,5100),('inazuma',8200,7700),('sumeru',3200,5700)]):
 save('locations',record('location','demo-'+r,'Study site '+str(i+1),'Учебная точка '+str(i+1),region=r,locationType='schematic',coordinates=dict(x=x,y=y,confidence='speculative'),existencePeriod=dict(startBP=900,endBP=0),historicalStatus='unknown'))
 save('events',record('event','demo-event-'+r,['An archive fragment','A changing settlement','Across the sea','A memory preserved'][i],['Фрагмент архива','Изменение поселения','За морем','Сохранённая память'][i],description=loc('Synthetic example only. The date, participants and location demonstrate the knowledge model; they do not assert a canonical event. Replace this record with researched content before using the archive as a reference.','Только учебный пример. Дата, участники и место демонстрируют модель данных, а не каноническое событие. Замените запись проверенными сведениями перед использованием архива как справочника.'),date=dict(type='approximate',yearsBeforePresent=500+i*20,uncertainty=80),regions=[r],locations=['demo-'+r],participants=['venti','dvalin'] if i==0 else ['zhongli'] if i==1 else [],relatedTerms=['irminsul'] if i==3 else [],summary=loc(['An example of connecting a historical fragment to people and place.','A sample record demonstrating uncertain settlement history.','A regional event placed alongside contemporary examples.','An example of relating a historical event to a shared concept.'][i],['Пример связи исторического фрагмента с людьми и местом.','Пример неопределённой истории поселения.','Региональное событие рядом с примерами того же периода.','Пример связи исторического события с общим понятием.'][i]),era='demo-era',eventType='research'))
save('events',record('event','demo-undated','An undated fragment','Недатированный фрагмент',date={'type':'relative','after':'demo-event-mondstadt'},regions=['mondstadt'],locations=[],participants=[],relatedTerms=[],summary=loc('A relative date without an invented numeric position.','Относительная дата без выдуманной числовой позиции.'),eventType='research'))
save('eras',record('era','demo-era','Sample research window','Учебный период',start=dict(type='approximate',yearsBeforePresent=700,uncertainty=100),end=dict(type='approximate',yearsBeforePresent=300,uncertainty=100)))
save('relationships',record('relationship','demo-venti-dvalin','Example connection','Пример связи',sourceCharacter='venti',targetCharacter='dvalin',relationshipType=loc('Relationship to research','Связь для исследования'),introducedInVersion='demo-1',evidenceStatus='theory'))
for i in [1,2]: save('versions',record('version','demo-'+str(i),'Demo patch '+str(i),'Учебный патч '+str(i),version='demo-'+str(i),order=i,status='demo',citationNeeded=False))
save('sources',record('source','demo-research-note','Research worksheet — demonstration','Исследовательская заметка — пример',sourceType='Other',gameVersion='demo-2',notes=loc('Synthetic workflow fixture, not an original game source and not evidence of lore. No external URL is asserted.','Учебная запись рабочего процесса, не первоисточник игры и не доказательство лора. Внешняя ссылка отсутствует.'),mentions=[dict(type='character',id='venti'),dict(type='event',id='demo-event-mondstadt'),dict(type='term',id='irminsul')],processingStatus='unprocessed',introducedInVersion='demo-2',createdInVersion='demo-2',lastModifiedInVersion='demo-2',lastReviewedInVersion='demo-2',citationNeeded=False))
save('claims',record('claim','demo-claim','A statement awaiting evidence','Утверждение, ожидающее доказательств',subject=dict(type='event',id='demo-event-mondstadt'),statement=loc('This synthetic claim demonstrates how an important interpretation is tracked. It is not a lore assertion.','Это учебное утверждение показывает отслеживание важных интерпретаций. Оно не утверждает фактов лора.'),introducedInVersion='demo-2',lastModifiedInVersion='demo-2',status='current',evidenceStatus='theory'))
save('map/geometry',record('geometry','demo-boundary','Schematic study area','Схематическая область исследования',geometryType='polygon',points=[[5800,1700],[7900,1900],[8100,3600],[6400,4100],[5500,2900]],citationNeeded=False))
save('map/territories',record('territory','demo-territory','Illustrative territory','Учебная территория',entity=dict(type='region',id='mondstadt'),period=dict(startBP=800,endBP=200),geometryId='demo-boundary',geographyConfidence='speculative'))
